{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    min_sum = sum(s['minimum'] for s in segments)
    cap_sum = sum(s['capacity'] for s in segments)
    if budget < min_sum or budget > cap_sum:
        raise ValueError("Budget out of range")
    allocated = [s['minimum'] for s in segments]
    remaining = budget - min_sum
    while remaining > 0:
        best_idx = -1
        for i in range(n):
            if allocated[i] >= segments[i]['capacity']:
                continue
            if best_idx == -1:
                best_idx = i
            else:
                lhs = segments[i]['importance'] * (allocated[best_idx] + 1)
                rhs = segments[best_idx]['importance'] * (allocated[i] + 1)
                if lhs > rhs:
                    best_idx = i
        if best_idx == -1:
            break
        allocated[best_idx] += 1
        remaining -= 1
    total = sum(allocated)
    name_mapping = {segments[i]['name']: allocated[i] for i in range(n)}
    return {"allocations": allocated, "name_mapping": name_mapping, "total_allocated": total}"}
